// Package jvm is the low-level bridge between Go and the JVM that Minecraft runs on: classes,
// methods, fields, Java interfaces implemented by Go closures, and Java subclasses overridden in Go.
//
// Most mods use the friendlier gocraft, mc, registry, event and command packages, or typed bindings
// generated by go.jar, and reach for this package when they need something those do not cover.
package jvm

// #include "bridge.h"
import "C"

import (
	"runtime"
)

// ref owns a handle. The JVM object it names stays alive at least as long as the ref.
//
// The pointer field keeps refs out of Go's tiny allocator, which packs small pointer-free objects into
// shared blocks that die together. A ref sharing a block with a callback's boxed id could then never be
// collected: the id lives until the proxy is collected, and the proxy lives until the ref is released.
type ref struct {
	id     int64
	noTiny *byte
}

// Object is a reference to a Java object. The zero value is Java's null.
type Object struct{ r *ref }

// Objecter is anything wrapping a Java object, including structs that embed Object.
type Objecter interface{ JavaObject() Object }

// JavaObject implements Objecter, so types embedding Object can be passed straight to Java.
func (o Object) JavaObject() Object { return o }

// IsNull reports whether o is Java's null.
func (o Object) IsNull() bool { return o.r == nil }

func (o Object) id() int64 {
	if o.r == nil {
		return 0
	}
	return o.r.id
}

var releases chan int64

// startReleaser funnels releases through one goroutine: cleanups must not block, and a single
// goroutine keeps the JVM from attaching a new thread for each of them.
func startReleaser() {
	releases = make(chan int64, 4096)
	go func() {
		for id := range releases {
			C.c_release(C.i64(id))
		}
	}()
}

func queueRelease(id int64) { releases <- id }

// wrap takes ownership of a handle from Java.
func wrap(id int64) Object {
	if id == 0 {
		return Object{}
	}
	r := &ref{id: id}
	runtime.AddCleanup(r, queueRelease, id)
	return Object{r: r}
}

func dupHandle(o Object) int64 {
	id := o.id()
	if id == 0 {
		return 0
	}
	dup := int64(C.c_dup(C.i64(id)))
	runtime.KeepAlive(o.r)
	return dup
}

// Same reports whether a and b are the same Java object (Java's ==).
func Same(a, b Objecter) bool {
	requireBooted()
	x, y := a.JavaObject(), b.JavaObject()
	same := C.c_same(C.i64(x.id()), C.i64(y.id())) != 0
	runtime.KeepAlive(x.r)
	runtime.KeepAlive(y.r)
	return same
}

// IsInstance reports whether o is an instance of c.
func (o Object) IsInstance(c *Class) bool {
	result := C.c_instance_of(C.i64(o.id()), C.i64(c.obj.id())) != 0
	runtime.KeepAlive(o.r)
	return result
}

// ClassOf returns o's runtime class, or an empty Object for null.
func (o Object) ClassOf() Object {
	requireBooted()
	result := wrap(int64(C.c_class_of(C.i64(o.id()))))
	runtime.KeepAlive(o.r)
	return result
}

// String returns Java's toString(), or "null".
func (o Object) String() string {
	if o.r == nil {
		return "null"
	}
	return readString(o)
}

// NewString creates a java.lang.String.
func NewString(s string) Object {
	requireBooted()
	return wrap(newStringHandle(s))
}

func newStringHandle(s string) int64 {
	id := int64(C.c_string_new(strAddr(s), C.i64(len(s))))
	runtime.KeepAlive(s)
	return id
}

func readString(o Object) string {
	var stack [256]byte
	n := int64(C.c_string_read(C.i64(o.id()), addr(stack[:]), C.i64(len(stack))))
	if n < 0 {
		runtime.KeepAlive(o.r)
		return ""
	}
	if n <= int64(len(stack)) {
		runtime.KeepAlive(o.r)
		return string(stack[:n])
	}

	buf := make([]byte, n)
	C.c_string_read(C.i64(o.id()), addr(buf), C.i64(n))
	runtime.KeepAlive(buf)
	runtime.KeepAlive(o.r)
	return string(buf)
}

// ArrayLen returns the length of a Java array.
func ArrayLen(o Objecter) int {
	requireBooted()
	obj := o.JavaObject()
	n := int(C.c_array_len(C.i64(obj.id())))
	runtime.KeepAlive(obj.r)
	return n
}

// NewBytes copies b into a new Java byte[].
func NewBytes(b []byte) Object {
	requireBooted()
	id := int64(C.c_bytes_new(addr(b), C.i64(len(b))))
	runtime.KeepAlive(b)
	return wrap(id)
}

// Bytes copies a Java byte[] into a new Go slice.
func Bytes(o Objecter) []byte {
	requireBooted()
	obj := o.JavaObject()
	n := int64(C.c_bytes_read(C.i64(obj.id()), nil, 0))
	if n <= 0 {
		runtime.KeepAlive(obj.r)
		return nil
	}

	buf := make([]byte, n)
	C.c_bytes_read(C.i64(obj.id()), addr(buf), C.i64(n))
	runtime.KeepAlive(buf)
	runtime.KeepAlive(obj.r)
	return buf
}

// Log levels accepted by Log.
const (
	LevelDebug = 0
	LevelInfo  = 1
	LevelWarn  = 2
	LevelError = 3
)

// Log writes to this mod's logger in the game log. Logging from package init is fine: messages wait
// until the mod has booted.
func Log(level int, message string) {
	if !booted.Load() {
		entryMu.Lock()
		if !booted.Load() {
			bootOnce = append(bootOnce, func() { Log(level, message) })
			entryMu.Unlock()
			return
		}
		entryMu.Unlock()
	}

	C.c_log(C.i64(token), C.i64(level), strAddr(message), C.i64(len(message)))
	runtime.KeepAlive(message)
}

// ModID returns the id of the running mod from gomod.json.
func ModID() string { return modID }
